#'"'"' Check if a function is log-concave at a set of points
#'"'"' 
#'"'"' @param density_func A function that computes the (possibly unnormalized) density
#'"'"' @param points A numeric vector of points to check
#'"'"' @param eps Small value for numerical differentiation
#'"'"' @return TRUE if log-concave at all points, FALSE otherwise
is_log_concave <- function(density_func, points, eps = 1e-6) {
  if (length(points) < 3) {
    return(TRUE)  # Can'"'"'t check concavity with fewer than 3 points
  }

  log_dens <- log(density_func(points))

  # Check second derivative is negative (concave)
  for (i in 2:(length(points) - 1)) {
    d2 <- (log_dens[i + 1] - 2 * log_dens[i] + log_dens[i - 1]) / (eps^2)
    if (d2 > 1e-8) {
      return(FALSE)
    }
  }
  return(TRUE)
}

#'"'"' Compute the supporting points and their logs
#'"'"' 
#'"'"' @param density_func The density function
#'"'"' @param points Numeric vector of initial points
#'"'"' @return A list with '"'"'x'"'"' (points) and '"'"'log_f'"'"' (log densities)
compute_supporting_points <- function(density_func, points) {
  log_f <- log(density_func(points))
  list(x = points, log_f = log_f)
}

#'"'"' Compute the tangent lines (supporting hyperplanes) at each supporting point
#'"'"' 
#'"'"' @param sp The supporting points list from compute_supporting_points
#'"'"' @return A list with '"'"'a'"'"' (slopes) and '"'"'b'"'"' (intercepts) for each tangent line
compute_tangents <- function(sp) {
  n <- length(sp$x)
  a <- numeric(n)
  b <- numeric(n)

  # Compute derivatives numerically using central differences
  for (i in 1:n) {
    eps <- 1e-6
    if (i == 1) {
      # Forward difference for first point
      slope <- (log(sp$log_f[i + 1]) - log(sp$log_f[i])) / (sp$x[i + 1] - sp$x[i])
    } else if (i == n) {
      # Backward difference for last point
      slope <- (log(sp$log_f[i]) - log(sp$log_f[i - 1])) / (sp$x[i] - sp$x[i - 1])
    } else {
      # Central difference
      slope <- (log(sp$log_f[i + 1]) - log(sp$log_f[i - 1])) / (sp$x[i + 1] - sp$x[i - 1])
    }
    a[i] <- slope
    b[i] <- sp$log_f[i] - slope * sp$x[i]
  }

  list(a = a, b = b)
}

#'"'"' Find the vertex of the piecewise linear upper bound
#'"'"' 
#'"'"' @param tangents The tangents list from compute_tangents
#'"'"' @return A list with '"'"'x_star'"'"' (vertex location) and '"'"'log_f_star'"'"' (upper bound value)
find_upper_bound_vertex <- function(tangents) {
  n <- length(tangents$a)

  # The upper bound is piecewise linear, with changes at the supporting points
  # Find where the slope changes from positive to negative
  for (i in 1:(n - 1)) {
