    # The upper bound at supporting point i+1 is tangent i+1
    # Find intersection of tangents i and i+1
    x_int <- (tangents$b[i + 1] - tangents$b[i]) / (tangents$a[i] - tangents$a[i + 1])

    if (x_int >= tangents$x[i] && x_int <= tangents$x[i + 1]) {
      log_f_star <- tangents$a[i] * x_int + tangents$b[i]
      return(list(x_star = x_int, log_f_star = log_f_star))
